static void filePath(char *p,const char *name){snprintf(p,96,"%s/%s",root,name);}
static void saveProfile(void){if(!storage)return;char p[96];filePath(p,"profile.dat");FILE*f=fopen(p,"wb");if(f){fwrite(profile,sizeof profile,1,f);fwrite(&unlocked,sizeof unlocked,1,f);fclose(f);}}

static const char *dimensions[]={"Acirema","Dimension X","Underworld","Avlique","Northwood","Storybend","Hawkins","Heaven"};
static void save(void){if(!storage)return; char p[96];filePath(p,"contacts.dat");FILE*f=fopen(p,"wb");if(!f){strcpy(notice,"Save failed");return;} fwrite(&count,sizeof count,1,f);fwrite(names,sizeof names,1,f);fwrite(dims,sizeof dims,1,f);fwrite(draft,sizeof draft,1,f);if(fclose(f))strcpy(notice,"Save failed");}
static void load(void){char p[96];filePath(p,"contacts.dat");FILE*f=fopen(p,"rb");if(!f)return; if(fread(&count,sizeof count,1,f)!=1||count<0||count>N||fread(names,sizeof names,1,f)!=1||fread(dims,sizeof dims,1,f)!=1||fread(draft,sizeof draft,1,f)!=1)count=0;fclose(f);for(int i=0;i<count;i++){names[i][31]=0;dims[i][23]=0;draft[i][LEN-1]=0;}}
static void chooseUser(int u){user=u;snprintf(root,sizeof root,"/Dimensionz/%s",users[u]);count=sel=0;unlocked=0;memset(names,0,sizeof names);memset(dims,0,sizeof dims);memset(draft,0,sizeof draft);memset(profile,0,sizeof profile);if(storage){mkdir(root,0777);load();char p[96];filePath(p,"profile.dat");FILE*f=fopen(p,"rb");if(f){if(fread(profile,sizeof profile,1,f)!=1)memset(profile,0,sizeof profile);if(fread(&unlocked,sizeof unlocked,1,f)!=1)unlocked=0;fclose(f);}}for(int i=0;i<4;i++)profile[i][LEN-1]=0;mode=profile[0][0]?0:6;profileField=0;strcpy(input,profile[0]);}
static void path(char*p){sprintf(p,"%s/chat%02d.txt",root,sel);}
static void append(char side){if(!input[0])return;if(!storage){strcpy(notice,"SD unavailable; not saved");return;}char p[96];path(p);FILE*f=fopen(p,"a");if(!f){strcpy(notice,"Cannot open chat file");return;}time_t now=time(NULL);struct tm*t=localtime(&now);char stamp[32]="Unknown time";if(t)strftime(stamp,sizeof stamp,"%m/%d/%y %H:%M",t);int ok;if(side=='N'){ok=fprintf(f,"Narration %s\n",stamp);for(int j=0;ok>=0&&input[j];){int len=strlen(input+j);if(len>31)len=31;ok=fprintf(f,"%*s%.*s\n",(31-len)/2,"",len,input+j);j+=len;}}else ok=fprintf(f,"%c %s\n%s\n",side,stamp,input);int closed=fclose(f);if(ok<0||closed){strcpy(notice,"Save failed");return;}input[0]=0;draft[sel][0]=0;save();scroll=0;strcpy(notice,"Saved to SD");}
static void add(char c){size_t n=strlen(input);if(n<LEN-1){input[n]=c;input[n+1]=0;}}
static void back(void){size_t n=strlen(input);if(n)input[n-1]=0;}
static void leave(void){if(mode==1||mode==3||mode==8){strcpy(draft[sel],input);save();}mode=0;input[0]=0;scroll=0;}
static void openchat(void){if(!count)return;mode=1;narrator=0;strcpy(input,draft[sel]);scroll=0;}

