static u16 *screens[2]; static u16 frame[2][256*192]; static int page=0;
#define C(r,g,b) (0x8000|RGB15((r)>>3,(g)>>3,(b)>>3))
#define BG C(20,17,30)
#define PANEL C(40,32,53)
#define TEAL C(0,125,134)
#define PURPLE C(53,45,67)
#define KEY C(80,66,95)
#define WHITE C(250,245,255)
#define MUTED C(195,183,210)
static void rect(int s,int x,int y,int w,int h,u16 c){for(int j=y;j<y+h;j++)if(j>=0&&j<192)for(int i=x;i<x+w;i++)if(i>=0&&i<256)frame[s][j*256+i]=c;}
static void roundbox(int s,int x,int y,int w,int h,u16 c){rect(s,x+3,y,w-6,h,c);rect(s,x,y+3,w,h-6,c);rect(s,x+1,y+1,w-2,h-2,c);}
static void text(int s,int x,int y,const char *t,u16 c){for(;*t;t++,x+=6){unsigned ch=(unsigned char)*t;if(ch<32||ch>126)ch='?';for(int j=0;j<12;j++)for(int i=0;i<6;i++)if(font[ch-32][j]&(1<<i))if(x+i>=0&&x+i<256&&y+j>=0&&y+j<192)frame[s][(y+j)*256+x+i]=c;}}
static void center(int s,int x,int y,int w,const char*t,u16 c){text(s,x+(w-(int)strlen(t)*6)/2,y,t,c);}
static void label(int s,int x,int y,int w,int h,const char*t,u16 c){roundbox(s,x,y,w,h,c);center(s,x,y+(h-12)/2,w,t,WHITE);}
static void portrait(int x,int y,const char *name){const unsigned short *a=avatar(name);roundbox(0,x,y,28,28,KEY);if(a){for(int j=0;j<28;j++)for(int i=0;i<28;i++)if((i-13)*(i-13)+(j-13)*(j-13)<190)frame[0][(y+j)*256+x+i]=a[j*28+i];}else{char t[2]={name[0],0};center(0,x,y+8,28,t,WHITE);}}
typedef struct {char side,stamp[32],body[LEN+1];} Msg;
static Msg msgs[128]; static int nm;
static void readmsgs(void){nm=0;char p[96],line[256];path(p);FILE*f=storage?fopen(p,"r"):NULL;if(!f)return;while(fgets(line,sizeof line,f)){line[strcspn(line,"\r\n")]=0;char side=0;char *stamp=NULL;if((line[0]=='>'||line[0]=='<')&&line[1]==' '){side=line[0];stamp=line+2;}else if(!strncmp(line,"Narration ",10)){side='N';stamp=line+10;}if(side){if(nm==128){memmove(msgs,msgs+1,127*sizeof(Msg));nm--;}Msg*m=&msgs[nm++];memset(m,0,sizeof *m);m->side=side;snprintf(m->stamp,sizeof m->stamp,"%.31s",stamp);}else if(nm){Msg*m=&msgs[nm-1];char *q=line;if(m->side=='N')while(*q==' ')q++;size_t n=strlen(m->body);if(n&&n<LEN-1)m->body[n++]=' ';snprintf(m->body+n,sizeof m->body-n,"%s",q);}}fclose(f);}
static void clockstr(const char *stamp,char *out){int mo,d,yr,h,m;if(sscanf(stamp,"%d/%d/%d %d:%d",&mo,&d,&yr,&h,&m)==5)snprintf(out,24,"%d:%02d %s",h%12?h%12:12,m,h>=12?"PM":"AM");else snprintf(out,24,"%.23s",stamp);}
static int wrap(const char *src,char lines[12][34],int max){int n=0;while(*src&&n<12){int len=strlen(src);if(len>max){len=max;int k=len;while(k>0&&src[k]!=' ')k--;if(k>0)len=k;}memcpy(lines[n],src,len);lines[n++][len]=0;src+=len;while(*src==' ')src++;}if(!n){lines[0][0]=0;n=1;}return n;}
static void conversation(void){rect(0,0,0,256,34,PANEL);portrait(5,3,names[sel]);text(0,39,3,names[sel],WHITE);text(0,39,17,dims[sel],MUTED);readmsgs();if(nm){char date[9];snprintf(date,sizeof date,"%.8s",msgs[nm-1].stamp);text(0,204,19,date,MUTED);}if(!nm)center(0,0,86,256,"No messages yet",MUTED);if(scroll>=nm)scroll=nm?nm-1:0;int y=176;for(int i=nm-1-scroll;i>=0;i--){Msg*m=&msgs[i];char lines[12][34],stamp[24];clockstr(m->stamp,stamp);int n=wrap(m->body,lines,m->side=='N'?33:29);int w=60;for(int j=0;j<n;j++)if((int)strlen(lines[j])*6+12>w)w=strlen(lines[j])*6+12;int h=n*12+17; y-=h;if(y<35)break;int x=m->side=='>'?251-w:5;if(m->side=='N'){for(int j=0;j<n;j++)center(0,0,y+j*12,256,lines[j],MUTED);center(0,0,y+n*12,256,stamp,MUTED);}else{roundbox(0,x,y,w,h,m->side=='>'?TEAL:PURPLE);for(int j=0;j<n;j++)text(0,x+6,y+2+j*12,lines[j],WHITE);text(0,x+w-5-strlen(stamp)*6,y+n*12+2,stamp,MUTED);}y-=4;}rect(0,0,178,256,14,PANEL);center(0,0,179,256,storage?"Fictional chat diary - SD":"SD unavailable",MUTED);}
static const char *letters[]={"qwertyuiop","asdfghjkl","zxcvbnm"};static const char *symbols[]={"1234567890","!@#$%&*()","-+/:;,.?"};
typedef struct {int x,y,w,h;char ch;const char *label;} K;
static K kb[40];static int nk;
static void putkey(int x,int y,int w,int h,char ch,const char*l){kb[nk++]=(K){x,y,w,h,ch,l};}
static void layout(void){nk=0;for(int r=0;r<3;r++){const char *a=page?symbols[r]:letters[r];int n=strlen(a),x=(256-n*24)/2;for(int j=0;j<n;j++)putkey(x+j*24,62+r*23,22,21,a[j],NULL);}putkey(5,132,38,20,1,page?"ABC":"123");putkey(46,132,38,20,2,"SHIFT");putkey(87,132,119,20,' ',"SPACE");putkey(209,132,42,20,3,"DEL");if(key>=nk)key=nk-1;}
static void activate(int i){if(i<0||i>=nk)return;char c=kb[i].ch;if(c==1){page=!page;key=0;}else if(c==2)upper=!upper;else if(c==3)back();else{if(upper&&c>='a'&&c<='z')c-=32;add(c);}}
static void move(int dx,int dy){int best=key,score=100000;K a=kb[key];for(int i=0;i<nk;i++){K b=kb[i];int x=b.x+b.w/2-a.x-a.w/2,y=b.y+b.h/2-a.y-a.h/2;if((dx&&y==0&&x*dx>0)||(dy&&y*dy>0)){int z=dx?abs(x):abs(y)*10+abs(x);if(z<score){score=z;best=i;}}}key=best;}
static void userCircle(int x,int y,int u){char name[32];snprintf(name,sizeof name,"USER:%s",users[u]);const unsigned short*a=avatar(name);for(int j=0;j<64;j++)for(int i=0;i<64;i++)if((i-32)*(i-32)+(j-32)*(j-32)<1024)frame[1][(y+j)*256+x+i]=a?a[(j*28/64)*28+i*28/64]:KEY; if(!a)center(1,x,y+25,64,"Guest",WHITE);center(1,x,y+70,64,users[u],WHITE);}
static const char *fields[]={"Name","Age","Gender","Biography"};
static void draw(void){rect(0,0,0,256,192,BG);rect(1,0,0,256,192,PANEL);if(mode==5){center(0,0,48,256,"DIMENSIONZ",WHITE);center(0,0,90,256,"Who are you?",WHITE);for(int i=0;i<3;i++)userCircle(8+i*84,48,i);center(1,0,155,256,"Tap your profile",MUTED);}else if(mode==0){text(0,8,6,"DIMENSIONZ / CHATS",WHITE);int start=sel>3?sel-3:0;for(int i=start;i<count&&i<start+4;i++){int y=25+(i-start)*39;roundbox(0,4,y,248,35,i==sel?TEAL:PURPLE);portrait(8,y+3,names[i]);text(0,42,y+3,names[i],WHITE);text(0,42,y+17,dims[i],MUTED);}if(!count)center(0,0,80,256,"No chats yet",MUTED);center(1,0,20,256,"A: Open chat",WHITE);center(1,0,43,256,"X: New contact",WHITE);center(1,0,66,256,"Y: Rename contact",WHITE);center(1,0,88,256,"SELECT: Settings",WHITE);center(1,0,112,256,storage?"SD saving enabled":"SD unavailable",MUTED);}else if(mode==8){center(0,0,40,256,"CHAT OPTIONS",WHITE);center(1,0,55,256,"B: Resume chat",WHITE);center(1,0,90,256,"START: Save and exit",WHITE);}else if(mode==7){center(0,0,30,256,"SETTINGS",WHITE);label(1,10,35,236,32,"Edit identity (A)",KEY);label(1,10,80,236,32,"Switch profile (X)",KEY);center(1,0,150,256,"B: Back",MUTED);}else{if(mode==1||mode==3)conversation();else if(mode==6){center(0,0,10,256,"Your identity",WHITE);for(int i=0;i<4;i++){text(0,8,32+i*30,fields[i],i==profileField?WHITE:MUTED);char v[40];snprintf(v,sizeof v,"%.39s",i==profileField?input:profile[i]);text(0,8,44+i*30,v,WHITE);}center(0,0,165,256,"START: Next / Save",MUTED);}else{text(0,8,8,mode==2?"NEW CONTACT":"RENAME CONTACT",WHITE);text(0,8,35,input,WHITE);if(mode==2){text(0,8,60,dimensions[dim],MUTED);text(0,8,76,"L/R: change dimension",MUTED);}text(0,8,100,"START: save contact",MUTED);}text(1,5,2,mode==3?"SCROLL MODE - SELECT to type":mode==1?(narrator?"NARRATOR ON - Y to switch":"CHAT MODE - Y: Narrator"):"CONTACT NAME",WHITE);roundbox(1,5,16,246,42,KEY);roundbox(1,6,17,244,40,BG);int n=strlen(input),start=n>78?n-78:0;char line[40];for(int j=0;j<2&&start+j*39<n;j++){snprintf(line,sizeof line,"%.39s",input+start+j*39);text(1,9,21+j*14,line,WHITE);}layout();for(int i=0;i<nk;i++){K k=kb[i];char t[2]={k.ch,0};if(upper&&t[0]>='a'&&t[0]<='z')t[0]-=32;label(1,k.x,k.y,k.w,k.h,k.label?k.label:t,i==key?TEAL:KEY);}if(mode==1||mode==3){label(1,5,156,121,22,narrator?"L - NARRATE":"L - SEND",TEAL);label(1,130,156,121,22,narrator?"R - NARRATE":"R - RECEIVE",KEY);}else label(1,5,156,246,22,mode==6?"START - NEXT / SAVE":"START - SAVE CONTACT",TEAL);center(1,0,180,256,notice[0]?notice:"START: chats  SELECT: scroll",MUTED);}for(int i=0;i<2;i++)memcpy(screens[i],frame[i],sizeof frame[i]);}
int main(void){videoSetMode(MODE_5_2D);videoSetModeSub(MODE_5_2D);vramSetBankA(VRAM_A_MAIN_BG);vramSetBankC(VRAM_C_SUB_BG);int a=bgInit(3,BgType_Bmp16,BgSize_B16_256x256,0,0),b=bgInitSub(3,BgType_Bmp16,BgSize_B16_256x256,0,0);screens[0]=(u16*)bgGetGfxPtr(a);screens[1]=(u16*)bgGetGfxPtr(b);lcdMainOnTop();storage=fatInitDefault();if(storage){mkdir("/Dimensionz",0777);}mode=5;draw();while(1){swiWaitForVBlank();scanKeys();int k=keysDown();int held=keysHeld();static int selectUsed=0, repeat=0;if(mode==1&&(held&KEY_SELECT)){if(held&(KEY_UP|KEY_DOWN)){selectUsed=1;if((repeat++%5)==0){if(held&KEY_UP)scroll++;else if(scroll>0)scroll--;draw();}}continue;}repeat=0;if(mode==1&&(keysUp()&KEY_SELECT)){if(!selectUsed){mode=8;draw();}selectUsed=0;continue;}if(!k)continue;if(mode==5){if(k&KEY_TOUCH){touchPosition t;touchRead(&t);if(t.py>=48&&t.py<132){int u=t.px/84;if(u<3)chooseUser(u);}}}else if(mode==7){if(k&KEY_TOUCH){touchPosition t;touchRead(&t);if(t.py>=35&&t.py<67)k|=KEY_A;if(t.py>=80&&t.py<112)k|=KEY_X;}if(k&KEY_A){profileField=0;strcpy(input,profile[0]);mode=6;}else if(k&KEY_X)mode=5;else if(k&KEY_B)mode=0;}else if(mode==8){if(k&KEY_B||k&KEY_SELECT)mode=1;else if(k&KEY_START)leave();}else if(mode==0){if(k&KEY_SELECT)mode=7;if((k&KEY_UP)&&sel>0)sel--;if((k&KEY_DOWN)&&sel+1<count)sel++;if(k&KEY_A)openchat();if((k&KEY_X)&&count<N){mode=2;input[0]=0;dim=1;}if((k&KEY_Y)&&count){mode=4;strcpy(input,names[sel]);}}else if(mode==3){if(k&KEY_UP)scroll++;if((k&KEY_DOWN)&&scroll>0)scroll--;if(k&KEY_SELECT)mode=1;if(k&KEY_START)leave();}else{layout();if(k&KEY_LEFT)move(-1,0);if(k&KEY_RIGHT)move(1,0);if(k&KEY_UP)move(0,-1);if(k&KEY_DOWN)move(0,1);if(k&KEY_A)activate(key);if(k&KEY_X)add(' ');if(k&KEY_B)back();if(k&KEY_Y){if(mode==1)narrator=!narrator;else upper=!upper;}if(k&KEY_TOUCH){touchPosition t;touchRead(&t);for(int i=0;i<nk;i++){K z=kb[i];if(t.px>=z.x&&t.px<z.x+z.w&&t.py>=z.y&&t.py<z.y+z.h){key=i;activate(i);break;}}if(t.py>=156&&t.py<178&&mode==1)k|=t.px<128?KEY_L:KEY_R;}if(mode==1){if(k&KEY_L)append(narrator?'N':'>');if(k&KEY_R)append(narrator?'N':'<');if(k&KEY_START)leave();}else if(mode==6){if(k&KEY_START){if(profileField==0&&!input[0]){strcpy(notice,"Enter your name");}else{strcpy(profile[profileField],input);if(++profileField==4){saveProfile();mode=0;input[0]=0;}else strcpy(input,profile[profileField]);}}}else{if(k&KEY_L)dim=(dim+7)%8;if(k&KEY_R)dim=(dim+1)%8;if((k&KEY_START)&&input[0]){if(mode==2){sel=count++;snprintf(dims[sel],24,"%s",dimensions[dim]);}snprintf(names[sel],32,"%.31s",input);save();mode=0;input[0]=0;}}}draw();}return 0;}
